"use client";
import React, { useState, useEffect } from "react";
import {
  Ruler,
  ArrowRight,
  Shirt,
  Footprints,
  Zap,
  Info,
  ChevronDown,
} from "lucide-react";
import { sizeData } from "@/data/sizes";
import { SlArrowRight } from "react-icons/sl";

export default function SizeGuidePage() {
  const [activeCat, setActiveCat] = useState<keyof typeof sizeData>("footwear");
  const [baseUnit, setBaseUnit] = useState<string>("");
  const [targetUnit, setTargetUnit] = useState<string>("");

  useEffect(() => {
    const availableUnits = sizeData[activeCat].units;
    setBaseUnit(availableUnits[0]);
    setTargetUnit(availableUnits[availableUnits.length - 1]);
  }, [activeCat]);

  const categories = [
    { id: "footwear", label: "Footwear", icon: <Footprints size={16} /> },
    { id: "apparel", label: "Apparel", icon: <Shirt size={16} /> },
  ];

  return (
    <div className="bg-background text-foreground min-h-screen pb-24 selection:bg-brand selection:text-white">
      {/* 1. EDITORIAL HEADER */}
      <header className="pt-16 pb-12 px-6 max-w-7xl mx-auto flex flex-col md:flex-row md:items-end justify-between gap-10">
        <div className="space-y-4">
          <div className="flex items-center gap-3 text-brand">
            <div className="h-[2px] w-12 bg-brand" />
            <span className="text-[11px] font-black uppercase tracking-[0.5em]">
              Global Standards
            </span>
          </div>
          <h1 className="text-7xl md:text-9xl font-black uppercase italic tracking-tighter leading-[0.8]">
            Fit <br /> <span className="opacity-20 italic">Architect</span>
          </h1>
        </div>

        <div className="max-w-70 space-y-4">
          <p className="text-[12px] font-bold uppercase leading-relaxed italic">
            Precision engineering for your silhouette. Our archive translates
            international metrics into a singular perfect fit.
          </p>
        </div>
      </header>

      {/* 2. CATEGORY SEGMENTED CONTROL */}
      <section className="px-6 mb-20">
        <div className="max-w-4xl mx-auto bg-muted/30 p-2 rounded-full border border-border flex gap-2">
          {categories.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActiveCat(cat.id as any)}
              className={`flex-1 flex items-center justify-center gap-3 py-5 rounded-full text-[11px] font-black uppercase tracking-widest transition-all duration-500 ${
                activeCat === cat.id
                  ? "bg-foreground text-background shadow-2xl scale-[1.02]"
                  : "hover:bg-muted/50"
              }`}
            >
              {cat.icon} <span>{cat.label}</span>
            </button>
          ))}
        </div>
      </section>

    
    </div>
  );
}
